import{_ as p,a0 as a,w as i,s as l,ao as r,I as s,x as n,a1 as o,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"如何在Ubuntu 13.04和13.10上安裝iOS 7的圖標 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 13.04和13.10上安裝iOS 7的圖標 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 13.04和13.10上安裝iOS 7的圖標 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 13.04和13.10上安裝iOS 7的圖標 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/How to Install the iOS 7 Icons in Ubuntu 13.04 and Ubuntu 13.10","title":"如何在Ubuntu 13.04和13.10上安裝iOS 7的圖標","tag":"201310","desc":""},"relativePath":"201310/How to Install the iOS 7 Icons in Ubuntu 13.04 and Ubuntu 13.10.md","filePath":"[post].md"}'),d={name:"201310/How to Install the iOS 7 Icons in Ubuntu 13.04 and Ubuntu 13.10.md"};function b(m,t,U,T,_,c){const e=a("Link");return i(),l("div",null,[t[11]||(t[11]=r(`<h1 id="如何在ubuntu-13-04和13-10上安裝ios-7的圖標" tabindex="-1">如何在Ubuntu 13.04和13.10上安裝iOS 7的圖標 <a class="header-anchor" href="#如何在ubuntu-13-04和13-10上安裝ios-7的圖標" aria-label="Permalink to “如何在Ubuntu 13.04和13.10上安裝iOS 7的圖標”">​</a></h1><p><strong>這個簡單的教程將指導你如何在你的Ubuntu 12.04、13.04和13.10上安裝蘋果iOS 7操作系統的所有圖標。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-the-iOS-7-Icons-in-Ubuntu-13-04-and-Ubuntu-13-10-387709-2.jpg" alt=""></p><p>上面是效果圖，安裝的圖標雖然並不多，但是對於外觀的改進來講卻是重大提高。如果Canonical沒有在每一個發行版中使用差異甚小的同類圖標，那你就不太容易分辨出Ubuntu。</p><p>以前在Ubuntu安裝主題、圖標甚至是鼠標光標，那叫一個麻煩，但是近幾年這事變得容易多了。想要安裝新的圖標，只需要輸入幾條命令就行。</p><p>在開始之前，請注意一下。本文使用的PPA(Personal Package Archives)只能在Ubuntu 12.04上運行。這是因為，在複製iOS的圖標時候是在Ubuntu 12.04版本上建立的。</p><p>當然，正如開始提到的，這些圖標可以在Ubuntu 13.04 和 Ubuntu 13.10上使用，只是需要改變一點小小的操作。</p><p>除此之外，你需要一個小軟件使這些圖標生效。我們推薦使用GNOME Tweak Tool，但是如果你喜歡的話還有幾個其他軟件可供選擇。</p><p>下面教程開始：</p><p>打開終端，安裝GNOME Tweak Tool：</p><pre><code>sudo apt-get install gnome-tweak-tool
</code></pre><p>你會發現這個軟件在Ubuntu下叫做Tweak Tool。</p><p>安裝PPA，然後更新一下：</p><pre><code>sudo add-apt-repository ppa:elementary-br/projects
sudo apt-get update
</code></pre><p>Ubuntu 12.04安裝iOS圖標：</p><pre><code>sudo apt-get install ieos7-icons
</code></pre><p>Ubuntu 13.04、Ubuntu 13.10安iOS裝圖標：</p><pre><code>wget -c https://launchpad.net/~elementary-br/+archive/projects/+files/ieos7-icons_0.1-0~13~ubuntu12.04.1_all.deb
sudo dpkg -i ieos7-icons_0.1-0~13~ubuntu12.04.1_all.deb
</code></pre><p>如果你發現deb包安裝失敗，無論什麼原因，只需要運行：</p><pre><code>sudo apt-get install -f
</code></pre><p>修復完依賴關係，再次運行：</p><pre><code>sudo dpkg -i ieos7-icons_0.1-0~13~ubuntu12.04.1_all.deb
</code></pre><p>這個圖標集大概有300個，所以你的操作系統中的部分應用程序圖標還是老樣子。</p><p>享受你的新圖標吧！</p><hr>`,25)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://news.softpedia.com/news/How-to-Install-the-iOS-7-Icons-in-Ubuntu-13-04-and-Ubuntu-13-10-387709.shtml"},{default:u(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/How-to-Install-the-iOS-7-Icons-in-Ubuntu-13-04-and-Ubuntu-13-10-387709.shtml",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:u(()=>[...t[3]||(t[3]=[n("Linux中國",-1)])]),_:1}),t[6]||(t[6]=n(" 榮譽推出",-1))]),s("p",null,[t[9]||(t[9]=n("譯者：",-1)),o(e,{href:"https://github.com/vic020"},{default:u(()=>[...t[7]||(t[7]=[n("Vic___",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),o(e,{href:"https://github.com/carolinewuyan"},{default:u(()=>[...t[8]||(t[8]=[n("carolinewuyan",-1)])]),_:1})])])}const w=p(d,[["render",b]]);export{g as __pageData,w as default};
